def _f(v, kind="num", d=1):
    if v is None or (isinstance(v, float) and np.isnan(v)):
        return "", ""
    if kind == "pct":
        return f"{v*100:+.{d}f}%" if d else f"{v*100:.0f}%", f"{v}"
    if kind == "pct0":
        return f"{v*100:.0f}%", f"{v}"
    if kind == "usd":
        return f"${v:,.0f}", f"{v}"
    if kind == "bn":
        return (f"${v/1e12:.2f}T" if v >= 1e12 else f"${v/1e9:.1f}B"), f"{v}"
    if kind == "x":
        return f"{v:.1f}x", f"{v}"
    return (f"{v:.{d}f}" if isinstance(v, (int, float)) else str(v)), f"{v}"


def _td(v, kind="num", d=1, cls=""):
    txt, raw = _f(v, kind, d)
    c = cls
    if kind in ("pct",) and txt:
        c += " pos" if v > 0 else " neg" if v < 0 else ""
    return f'<td class="{c.strip()}" data-v="{raw}">{txt}</td>'


def _kpi(v, label, sub=""):
    return f'<div class="card kpi"><div class="v">{v}</div><div class="l">{label}</div><div class="s">{sub}</div></div>'


def _plotly_json(fig: dict) -> str:
    return json.dumps(fig, default=lambda o: o.item() if hasattr(o, "item") else str(o))


def build(ctx: dict) -> Path:
    asof = ctx["asof"].strftime("%Y-%m-%d") if hasattr(ctx["asof"], "strftime") else str(ctx["asof"])
    top = ctx["top"].sort_values("rank"); uni = ctx["universe"]; res = ctx["res"]; opt = res["opt"]; ms = opt["recommended"]
    w = ms["weights"]; kpi = ctx["kpi"]; alerts = ctx["alerts"]; changes = ctx["changes"]; macro = ctx["macro_snapshot"]
    bt = res["backtest"]; px = ctx["px"]
    n_crit = sum(a["severity"] == "critical" for a in alerts); n_warn = sum(a["severity"] == "warning" for a in alerts)
    pb = ctx["pitchbook"]
    run = ctx.get("run") or {}

    # ---------- header & KPI strip ----------
    parts = [f'<div class="wrap"><div class="eyebrow">US Equity Research · Technology</div><h1>AI &amp; Semiconductor Value Chain — Daily KPI Monitor</h1>'
             f'<div class="sub">Top-15 undervalued / high-growth list and re-optimised portfolio · data as of <b>{asof}</b> · generated {datetime.now().strftime("%Y-%m-%d %H:%M")}</div>'
             f'<div class="status"><span>SEC EDGAR ✓ {int(uni["in_edgar"].sum())}/{len(uni)} issuers</span><span>Yahoo Finance ✓ prices to {px.index[-1].date()}</span>'
             f'<span>FRED ✓ 10Y {macro.loc["DGS10","value"]:.2f}%</span><span>{"PitchBook ✓" if pb["available"] else "PitchBook — not connected"}</span>'
             f'<span>Approved prior run: {changes.get("prev_run_id") or changes.get("prev_date") or "none"}</span></div>'
             f'<div class="status"><span class="chip warning">{run.get("validation_status", "NOT VALIDATED · exploratory")}</span><span>run {run.get("run_id", "-")}</span>'
             f'<span>{"actionable" if run.get("actionable", True) else "NOT ACTIONABLE: " + "; ".join(run.get("not_actionable_reasons", []))}</span>'
             f'<span>weights are model targets, no live position ledger</span></div>']
    parts.append('<h2>Portfolio &amp; screen KPIs</h2><div class="grid g4">'
                 + _kpi(f"{ms['exp_return']*100:.1f}%", "Expected return (recommended)", f"ERC, 25% vol target, cash {ms.get('cash', 0)*100:.0f}%")
                 + _kpi(f"{ms['vol']*100:.1f}%", "Expected volatility", "Ledoit-Wolf, 3-yr daily")
                 + _kpi(f"{ms['sharpe']:.2f}", "Sharpe ratio", f"rf {ctx['rf']*100:.2f}% (10Y Treasury)")
                 + _kpi(f"{top['upside'].median()*100:+.0f}%", "Median blended upside, top 15", f"universe median {uni['upside'].median()*100:+.0f}%")
                 + _kpi(f"{len(alerts)}", "Alerts today", f'<span class="chip critical">{n_crit} critical</span><span class="chip warning">{n_warn} warning</span>')
                 + _kpi(f"{(changes.get('turnover') or 0)*100:.0f}%", "Turnover vs approved prior run", f"{len(changes.get('entries', []))} entries · {len(changes.get('exits', []))} exits · incl. cash")
                 + _kpi(f"{top['rev_growth_ntm'].median()*100:.0f}%", "Median NTM revenue growth", "consensus, fiscal-year aligned")
                 + _kpi(f"{macro.loc['SEMI_IP_YOY','value']:+.1f}%", "Semiconductor output YoY", f"FRED IPG3344S · {macro.loc['SEMI_IP_YOY','date']}")
                 + '</div>')

    # ---------- alerts ----------
    parts.append('<div class="grid g2" style="margin-top:14px"><div class="card"><h3 style="margin-top:0">Alerts</h3>')
    if alerts:
        for a in alerts[:40]:
            parts.append(f'<div class="alert"><span class="chip {a["severity"]}">{a["severity"]}</span><div><b>{a["ticker"]}</b> <span class="tag">{a["type"]}</span> {a["message"]}</div></div>')
    else:
        parts.append('<div class="muted">No alerts.</div>')
    parts.append('</div><div class="card"><h3 style="margin-top:0">Changes vs previous run</h3>')
    if changes.get("prev_date"):
        parts.append(f'<div><b>Entries:</b> {", ".join(changes["entries"]) or "none"} &nbsp; <b>Exits:</b> {", ".join(changes["exits"]) or "none"}</div>')
        wc = changes.get("weight_changes", {})
        parts.append('<div style="margin-top:8px"><b>Largest weight moves:</b> ' + ", ".join(f"{t} {v:+.1%}" for t, v in list(wc.items())[:8]) + '</div>')
        rc = changes.get("rank_changes", {})
        parts.append('<div style="margin-top:8px"><b>Rank moves:</b> ' + ", ".join(f"{t} {v:+d}" for t, v in sorted(rc.items(), key=lambda kv: -abs(kv[1]))[:8] if v) + '</div>')
    else:
        parts.append('<div class="muted">First run — no previous snapshot to compare.</div>')
    parts.append('</div></div>')

    # ---------- top 15 table ----------
    parts.append('<h2>Top 15 — KPI table</h2><div class="tbl"><table><thead><tr><th class="l">#</th><th class="l">Ticker</th><th class="l">Company</th><th class="l">Segment</th><th class="l">Style</th>'
                 '<th>Weight</th><th>Price</th><th>1D</th><th>1W</th><th>1M</th><th>Fair value</th><th>Upside</th><th>Decision</th><th>Value</th><th>Growth</th><th>Momentum</th><th>Scarcity</th><th>Risk</th><th>Alpha diag.</th><th class="l">Risk flags</th><th>EV/S NTM</th><th>P/E NTM</th><th>NTM growth</th><th>FCF mgn</th>'
                 '<th>EPS rev 30d</th><th>EPS rev 90d</th><th>vs 200d</th><th class="l">Next earnings</th><th>Filings 30d</th><th class="l">10-K</th></tr></thead><tbody>')
    for t, r in kpi.sort_values("rank").iterrows():
        link = f'<a href="{r["latest_10k_url"]}" target="_blank">10-K</a>' if isinstance(r.get("latest_10k_url"), str) else ""
        ne = str(r.get("next_earnings") or "")[:10]
        parts.append(f'<tr><td class="l">{int(r["rank"])}</td><td class="l"><b>{t}</b></td><td class="l">{r["name"]}</td><td class="l">{r["segment"]}</td><td class="l">{r["style"]}</td>'
                     + _td(r["weight"], "pct0") + _td(r["price"], "usd") + _td(r["ret_1d"], "pct") + _td(r["ret_1w"], "pct") + _td(r["ret_1m"], "pct")
                     + _td(r["fair_value"], "usd") + _td(r["upside"], "pct", 0) + _td(r["composite"], "num", 2) + _td(r.get("score_value"), "num", 2) + _td(r.get("score_growth"), "num", 2) + _td(r.get("score_momentum"), "num", 2) + _td(r.get("score_scarcity"), "num", 2) + _td(r.get("score_risk"), "num", 2) + _td(r.get("alpha_score"), "num", 2) + f'<td class="l">{r.get("risk_flags") or ""}</td>' + _td(r["ev_sales_ntm"], "x") + _td(r["pe_ntm"], "x")
                     + _td(r["rev_growth_ntm"], "pct0") + _td(r["fcf_margin"], "pct0") + _td(r["eps_rev_30d"], "pct") + _td(r["eps_rev_90d"], "pct") + _td(r["vs_200dma"], "pct")
                     + f'<td class="l">{ne}</td>' + _td(r["filings_30d"], "num", 0) + f'<td class="l">{link}</td></tr>')
    parts.append('</tbody></table></div><div class="muted">Click a column header to sort. Upside = blended fair value (50% DCF, 30% regression multiple, 20% Street target) vs price.</div>')

    # ---------- portfolio ----------
    parts.append('<h2>Portfolio</h2><div class="grid g2"><div class="card"><div id="pw" class="plot"></div></div><div class="card"><div id="rc" class="plot"></div></div></div>')
    portfolio_methods = ["recommended", *opt.get("meta", {}).get("methods", [])]
    portfolio_methods = list(dict.fromkeys(k for k in portfolio_methods if k in opt))
    pstats = pd.DataFrame({k: {"Label": opt[k].get("label", k), "Family": opt[k].get("family", ""),
                                      "Return model": opt[k].get("return_model", ""), "E[return]": opt[k]["exp_return"],
                                      "Volatility": opt[k]["vol"], "Sharpe": opt[k]["sharpe"]}
                               for k in portfolio_methods}).T
    parts.append('<div class="grid g2" style="margin-top:12px"><div class="card"><h3 style="margin-top:0">Candidate portfolios</h3><div class="tbl" style="max-height:330px;border:0"><table><thead><tr><th class="l">Portfolio</th><th class="l">Family</th><th class="l">Return model</th><th>E[return]</th><th>Volatility</th><th>Sharpe</th></tr></thead><tbody>')
    for k, r in pstats.iterrows():
        parts.append(f'<tr><td class="l">{r["Label"]}</td><td class="l">{r["Family"]}</td><td class="l">{r["Return model"]}</td>'
                     f'{_td(r["E[return]"], "pct0")}{_td(r["Volatility"], "pct0")}{_td(r["Sharpe"], "num", 2)}</tr>')
    parts.append('</tbody></table></div></div><div class="card"><h3 style="margin-top:0">Target weights by portfolio</h3><div class="tbl" style="max-height:330px;border:0"><table><thead><tr><th class="l">Ticker</th><th>Recommended</th><th>Min var</th><th>Risk parity</th><th>Equal</th><th>Risk share</th><th>E[r] BL</th><th>Vol</th></tr></thead><tbody>')
    for t in w.sort_values(ascending=False).index:
        parts.append(f'<tr><td class="l"><b>{t}</b></td>{_td(opt["recommended"]["weights"][t], "pct0")}{_td(opt["min_vol"]["weights"][t], "pct0")}{_td(opt["risk_parity"]["weights"][t], "pct0")}{_td(opt["equal_weight"]["weights"][t], "pct0")}'
                     f'{_td(ms["risk_contrib"][t], "pct0")}{_td(res["asset_stats"].loc[t, "exp_return_bl"], "pct0")}{_td(res["asset_stats"].loc[t, "vol"], "pct0")}</tr>')
    parts.append('</tbody></table></div></div></div>')
    parts.append('<div class="grid g2" style="margin-top:12px"><div class="card"><div id="bt" class="plot"></div></div><div class="card"><div id="corr" class="plot"></div></div></div>')

    # ---------- universe ----------
    parts.append('<h2>Universe ranking (all scored companies)</h2><div class="card"><div id="vg" class="plot tall"></div></div>')
    parts.append('<div class="tbl" style="margin-top:12px"><table><thead><tr><th class="l">Rank</th><th class="l">Ticker</th><th class="l">Company</th><th class="l">Segment</th><th class="l">Style</th><th>Decision</th><th>Value</th><th>Growth</th><th>Momentum</th><th>Scarcity</th><th>Risk</th><th>Alpha diag.</th><th class="l">Risk flags</th><th>Quality diag.</th>'
                 '<th>Mkt cap</th><th>Upside</th><th>EV/S NTM</th><th>P/E NTM</th><th>NTM growth</th><th>Gross mgn</th><th>FCF mgn</th><th>ROIC</th><th>EPS rev 90d</th><th>6M vs SOXX</th><th class="l">Eligible</th></tr></thead><tbody>')
    for t, r in uni.sort_values("composite", ascending=False).iterrows():
        parts.append(f'<tr><td class="l">{int(r["rank_all"])}</td><td class="l"><b>{t}</b></td><td class="l">{r["name"]}</td><td class="l">{r["segment"]}</td><td class="l">{r["style"]}</td>'
                     + _td(r["composite"], "num", 2) + _td(r["score_value"], "num", 2) + _td(r["score_growth"], "num", 2) + _td(r["score_momentum"], "num", 2) + _td(r.get("score_scarcity"), "num", 2) + _td(r.get("score_risk"), "num", 2) + _td(r.get("alpha_score"), "num", 2) + f'<td class="l">{r.get("risk_flags") or ""}</td>' + _td(r["score_quality"], "num", 2)
                     + _td(r["market_cap"], "bn") + _td(r["upside"], "pct", 0) + _td(r["ev_sales_ntm"], "x") + _td(r["pe_ntm"], "x") + _td(r["rev_growth_ntm"], "pct0") + _td(r["gross_margin"], "pct0")
                     + _td(r["fcf_margin"], "pct0") + _td(r["roic"], "pct0") + _td(r["eps_rev_90d"], "pct") + _td(r["rel_6m_vs_soxx"], "pct") + f'<td class="l">{"yes" if r["eligible"] else "no"}</td></tr>')
    parts.append('</tbody></table></div>')

    # ---------- strategic role (LLM research) ----------
    from ..analysis import strategic as STR
    sa = STR.load_all()
    st = uni[[c for c in ["name", "segment", "strategic_score", "scarcity_strength", "risk_score", "financial_risk", "strategic_pillar", "news_direction",
                          "strategic_confidence", "strategic_asof", "strategic_stale", "risk_eligible", "risk_capped", "strategic_thesis", "kill_criteria", "rank_all"] if c in uni.columns]].copy()
    n_ass = int(st["strategic_score"].notna().sum()) if "strategic_score" in st else 0
    rq = ctx.get("strategic_refresh", {})
    parts.append('<h2>Strategic role: scarcity and risk (LLM deep research, evidence-logged)</h2>')
    parts.append(f'<div class="status"><span>Assessed {n_ass}/{len(st)}</span><span>Stale (&gt;90d) {int(st["strategic_stale"].sum()) if "strategic_stale" in st else 0}</span>'
                 f'<span>Refresh queue {rq.get("queued", 0)}</span><span>Assessor {"dry-run (set ANTHROPIC_API_KEY)" if rq.get("dry_run", True) else "Claude API"}</span>'
                 f'<span>Gate: risk &ge; {STR.RISK_GATE} excluded unless scarcity &ge; {STR.RISK_GATE_SCARCITY_OVERRIDE} (then weight cap {STR.HIGH_RISK_WEIGHT_CAP:.0%})</span></div>')
    parts.append('<div class="tbl" style="margin-top:10px"><table><thead><tr><th class="l">Ticker</th><th class="l">Segment</th><th>Rank</th><th>Scarcity</th><th>Risk</th><th>Fin. risk</th><th>Pillar</th><th>News 90d</th><th>Conf.</th><th class="l">As of</th><th class="l">Gate</th><th class="l">Thesis</th></tr></thead><tbody>')
    for t, r in st.dropna(subset=["strategic_score"]).sort_values("strategic_pillar", ascending=False).iterrows():
        gate = "capped" if bool(r.get("risk_capped")) else ("excluded" if not bool(r.get("risk_eligible", True)) else "ok")
        parts.append(f'<tr><td class="l"><b>{t}</b></td><td class="l">{r["segment"]}</td>{_td(r.get("rank_all"), "num", 0)}{_td(r["scarcity_strength"], "num", 2)}{_td(r["risk_score"], "num", 2)}{_td(r["financial_risk"], "num", 2)}'
                     f'{_td(r["strategic_pillar"], "num", 2)}{_td(r["news_direction"], "num", 2)}{_td(r["strategic_confidence"], "num", 2)}<td class="l">{r["strategic_asof"]}</td><td class="l">{gate}</td><td class="l" style="white-space:normal;min-width:320px">{r["strategic_thesis"] or ""}</td></tr>')
    parts.append('</tbody></table></div>')
    # evidence for the top 15
    parts.append('<div class="grid g2" style="margin-top:12px">')
    for t in top.index:
        a = sa.get(t)
        if not a:
            parts.append(f'<div class="card"><b>{t}</b> <span class="tag">no assessment yet</span><div class="muted">Queued for LLM research; pillar neutral until assessed.</div></div>'); continue
        dims = a["dimensions"]
        dim_txt = " · ".join(f'{k.replace("_", " ")} {STR._d(dims, k):.2f}' for k in list(STR.DIMENSION_WEIGHTS) + ["customer_concentration"] if k in dims)
        ev = "".join(f'<li><span class="mono">{e.get("date", "")}</span> <b>{e.get("direction", "")}</b> {e.get("claim", "")} <span class="muted">({e.get("source", "")})</span></li>' for e in a.get("evidence", [])[:6])
        kc = "".join(f"<li>{k}</li>" for k in a.get("kill_criteria", []))
        parts.append(f'<details class="card"><summary><b>{t}</b> · scarcity {STR.scarcity_strength(dims):.2f} · risk {STR.llm_risk(dims):.2f} (LLM) · v{a.get("version", 1)} {a.get("asof")} · confidence {a.get("confidence", 0):.2f}</summary>'
                     f'<div style="margin-top:8px"><b>Thesis.</b> {a.get("thesis", "")}</div><div class="muted" style="margin:6px 0">{dim_txt}</div>'
                     f'<div><b>Kill criteria</b><ul>{kc}</ul></div><div><b>Evidence</b><ul>{ev}</ul></div></details>')
    parts.append('</div>')

    # ---------- model health ----------
    val = ctx.get("validation"); live = ctx.get("live_validation") or {}
    parts.append('<h2>Model health: does the score predict returns?</h2>')
    parts.append('<div class="grid g2"><div class="card"><h3 style="margin-top:0">Point-in-time backtest (trailing-only score, SEC EDGAR filing dates)</h3>')
    if val:
        ic = pd.DataFrame(val["ic"]); piv = ic.pivot(index="signal", columns="horizon", values="mean_ic").reindex(columns=["1m", "3m", "6m", "12m"])
        tpiv = ic.pivot(index="signal", columns="horizon", values="t_hac").reindex(columns=["1m", "3m", "6m", "12m"])
        parts.append(f'<div class="muted">{val["panel"]["n_tickers"]} tickers · {val["panel"]["n_months"]} month-ends {val["panel"]["start"]} to {val["panel"]["end"]} · generated {val["generated_at"][:10]}</div>')
        parts.append('<table><thead><tr><th class="l">Signal</th><th>IC 1m</th><th>IC 3m</th><th>IC 6m</th><th>IC 12m</th><th>t (3m)</th></tr></thead><tbody>')
        for sig in ["composite", "alpha_score", "score_scarcity", "score_risk_resilience", "score_fund_momentum", "score_price_momentum", "score_value", "score_growth", "score_quality", "score_momentum"]:
            if sig in piv.index:
                parts.append(f'<tr><td class="l">{sig.replace("score_", "")}</td>' + "".join(_td(piv.loc[sig, h], "num", 3) for h in ["1m", "3m", "6m", "12m"]) + _td(tpiv.loc[sig, "3m"], "num", 2) + '</tr>')
        parts.append('</tbody></table>')
        bs = val["backtest_stats"]; pm = val["permutation"]; rw = val["random_weights"]; fr_ = val["factor_regression"]["top15_vs_spy_soxx"]
        parts.append('<div class="grid g4" style="margin-top:10px">'
                     + _kpi(f"{bs['top15']['cagr']*100:.1f}%", "Top-15 CAGR (gross)", f"universe EW {bs['universe_ew']['cagr']*100:.1f}% · SOXX {bs['SOXX']['cagr']*100:.1f}%")
                     + _kpi(f"{bs['ls_q5_q1']['cagr']*100:+.1f}%", "Q5 minus Q1 spread p.a.", f"hit rate vs universe {bs['top15']['hit_rate_vs_universe']*100:.0f}%")
                     + _kpi(f"{pm['p_value']:.3f}", "Permutation p-value (3m IC)", f"actual IC {pm['actual_mean_ic']:.3f} vs null {pm['null_mean']:.3f}")
                     + _kpi(f"{fr_['alpha_annual']*100:+.1f}%", "Alpha vs SPY + SOXX p.a.", f"t = {fr_['alpha_t']:.2f} · weights at {rw['percentile_of_actual']*100:.0f}th pctile of random")
                     + '</div>')
        parts.append(f'<div class="muted" style="margin-top:8px">{val["interpretation"]}</div>')
    else:
        parts.append('<div class="muted">No validation run yet: python scripts/run_validation.py</div>')
    parts.append('</div><div class="card"><h3 style="margin-top:0">Live forward IC from the daily archive (look-ahead-free)</h3>')
    if live.get("status") == "ok" and live.get("ic"):
        parts.append(f'<div class="muted">{live["n_snapshots"]} daily snapshots; snapshots with realised forward returns: {live["snapshots_with_forward"]}</div>')
        parts.append('<table><thead><tr><th class="l">Horizon</th><th class="l">Signal</th><th>Mean IC</th><th>t</th><th>Periods</th></tr></thead><tbody>')
        for h, sigs in live["ic"].items():
            for sig, v in sigs.items():
                parts.append(f'<tr><td class="l">{h}</td><td class="l">{sig}</td>{_td(v["mean_ic"], "num", 3)}{_td(v["t_stat"], "num", 2)}{_td(v["n_periods"], "num", 0)}</tr>')
        parts.append('</tbody></table>')
        if live.get("top15_vs_universe"):
            parts.append('<table style="margin-top:8px"><thead><tr><th class="l">Horizon</th><th>Top 15</th><th>Universe EW</th><th>SOXX</th><th>N</th></tr></thead><tbody>')
            for h, v in live["top15_vs_universe"].items():
                parts.append(f'<tr><td class="l">{h}</td>{_td(v["top15"], "pct")}{_td(v["universe_ew"], "pct")}{_td(v["soxx"], "pct")}{_td(v["n"], "num", 0)}</tr>')
            parts.append('</tbody></table>')
    else:
        parts.append(f'<div class="muted">Status: {live.get("status", "not computed")}. {live.get("n_snapshots", 0)} daily snapshot(s) archived so far; the first 1-month forward IC appears after ~21 trading days, 3-month after ~63. Every run appends the full universe score table to outputs/history/universe_panel.csv and the raw consensus to history/&lt;date&gt;/consensus_snapshot.json.</div>')
    parts.append('</div></div>')
    if val:
        parts.append('<div class="grid g2" style="margin-top:12px"><div class="card"><img src="../validation/charts/ic_timeseries_3m.png" style="width:100%" alt="IC time series"></div><div class="card"><img src="../validation/charts/quintiles.png" style="width:100%" alt="quintiles"></div></div>')

    # ---------- macro ----------
    parts.append('<h2>Macro (FRED)</h2><div class="tbl" style="max-height:420px"><table><thead><tr><th class="l">Series</th><th class="l">Indicator</th><th class="l">Date</th><th>Value</th><th>3M chg</th><th>12M chg</th></tr></thead><tbody>')
    for sid, r in macro.iterrows():
        parts.append(f'<tr><td class="l">{sid}</td><td class="l">{r["label"]}</td><td class="l">{r["date"]}</td>{_td(r["value"], "num", 2)}{_td(r["chg_3m"], "num", 2)}{_td(r["chg_12m"], "num", 2)}</tr>')
    parts.append('</tbody></table></div>')

    # ---------- history ----------
    hist_fig = None
    runs_path = HISTORY / "runs.csv"
    if runs_path.exists():
        runs = pd.read_csv(runs_path)
        if runs["date"].nunique() > 1:
            parts.append('<h2>Run history</h2><div class="grid g2"><div class="card"><div id="hw" class="plot"></div></div><div class="card"><div id="hr" class="plot"></div></div></div>')
            # A date can contain multiple immutable reruns.  Keep those runs distinct on the
            # chart and collapse only genuine duplicate rows inside the same run.
            run_id = runs["run_id"].fillna(runs["date"]).astype(str) if "run_id" in runs else runs["date"].astype(str)
            runs["run_axis"] = runs["date"].astype(str) + " · " + run_id
            hist_fig = runs.drop_duplicates(["run_axis", "ticker"], keep="last")

    parts.append('<div class="foot">Sources: SEC EDGAR XBRL company facts &amp; filing index; Yahoo Finance via yfinance (prices, statements, consensus); FRED. '
                 f'{pb["status"]} Methodology: five-pillar decision score = growth 37.5% + momentum 26.25% + value 11.25% + scarcity 15% + risk resilience 10%. Scarcity and risk are research priors pending live validation. Blended fair value and an equal-risk-contribution portfolio use 2–15% weight and 35% segment caps, scaled to a 25% volatility target (see docs/SCARCITY_RISK_SCORE.md). '
                 'For research discussion only; not investment advice.</div></div>')

    # ---------- plotly figures ----------
    grp = top["segment"].map(MACRO_GROUP)
    gcol = {"Design & Equipment": CAT[0], "Silicon": CAT[1], "Infrastructure & Power": CAT[2], "Cloud & Software": CAT[3]}
    ws = w.sort_values()
    fig_pw = {"data": [{"type": "bar", "orientation": "h", "x": ws.values.tolist(), "y": ws.index.tolist(), "marker": {"color": [gcol[grp[t]] for t in ws.index]},
                        "text": [f"{v:.1%}" for v in ws.values], "textposition": "outside", "hovertemplate": "%{y}: %{x:.1%}<extra></extra>"}],
              "layout": {"title": {"text": "Recommended target weights (ERC, vol-targeted)", "x": 0}, "margin": {"l": 60, "r": 20, "t": 40, "b": 30}, "xaxis": {"tickformat": ".0%", "range": [0, float(ws.max()) * 1.25]}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
    rc = ms["risk_contrib"].reindex(ws.index)
    fig_rc = {"data": [{"type": "bar", "orientation": "h", "name": "Weight", "x": ws.values.tolist(), "y": ws.index.tolist(), "marker": {"color": CAT[0]}},
                       {"type": "bar", "orientation": "h", "name": "Risk share", "x": rc.values.tolist(), "y": ws.index.tolist(), "marker": {"color": CAT[1]}}],
              "layout": {"title": {"text": "Weight vs risk contribution", "x": 0}, "barmode": "group", "margin": {"l": 60, "r": 20, "t": 40, "b": 30}, "xaxis": {"tickformat": ".0%"}, "legend": {"orientation": "h", "y": 1.08}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
    cum = bt["cumulative"] * 100
    fig_bt = {"data": [{"type": "scatter", "mode": "lines", "name": c, "x": [d.strftime("%Y-%m-%d") for d in cum.index], "y": cum[c].round(2).tolist(),
                        "line": {"color": CAT[i], "width": 2.4 if c == "Portfolio" else 1.4}} for i, c in enumerate(cum.columns)],
              "layout": {"title": {"text": "HINDSIGHT ILLUSTRATION - INVALID AS TRACK RECORD: today's target weights replayed, growth of 100", "x": 0}, "margin": {"l": 50, "r": 20, "t": 40, "b": 30}, "yaxis": {"type": "log"}, "hovermode": "x unified", "legend": {"orientation": "h", "y": 1.08}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
    corr = res["corr"]
    fig_corr = {"data": [{"type": "heatmap", "z": corr.round(2).values.tolist(), "x": corr.columns.tolist(), "y": corr.index.tolist(), "zmin": -1, "zmax": 1,
                          "colorscale": [[0, "#e34948"], [0.5, "#f0efec"], [1, "#2a78d6"]], "hovertemplate": "%{y} × %{x}: %{z:.2f}<extra></extra>"}],
                "layout": {"title": {"text": "Return correlations (3 years, daily)", "x": 0}, "margin": {"l": 60, "r": 20, "t": 40, "b": 50}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
    d = uni[uni["ev_sales_ntm"].between(0.2, 80) & uni["rev_growth_ntm"].between(-0.3, 2.5)]
    rest = d[~d.index.isin(top.index)]; pk = d[d.index.isin(top.index)]
    def _sc(df, name, color, size_scale=True):
        return {"type": "scatter", "mode": "markers+text" if name.startswith("Top") else "markers", "name": name, "x": df["rev_growth_ntm"].tolist(), "y": df["ev_sales_ntm"].tolist(),
                "text": df.index.tolist(), "textposition": "top center", "textfont": {"size": 10},
                "customdata": [[df.loc[t, "name"], df.loc[t, "segment"], df.loc[t, "upside"], df.loc[t, "composite"], df.loc[t, "fcf_margin"]] for t in df.index],
                "marker": {"color": color, "size": (np.sqrt(df["market_cap"].fillna(1e9) / 1e9) * 1.6 + 6).tolist(), "line": {"color": "#ffffff", "width": 1}, "opacity": 0.85 if name.startswith("Top") else 0.55},
                "hovertemplate": "<b>%{text}</b> %{customdata[0]}<br>%{customdata[1]}<br>NTM growth %{x:.0%} · EV/S %{y:.1f}x<br>Upside %{customdata[2]:+.0%} · score %{customdata[3]:.2f} · FCF margin %{customdata[4]:.0%}<extra></extra>"}
    fig_vg = {"data": [_sc(rest, "Universe", "#b8b7b0"), _sc(pk, "Top 15", CAT[0])],
              "layout": {"title": {"text": "Growth-adjusted valuation: EV/NTM sales vs consensus NTM revenue growth (bubble = market cap)", "x": 0}, "xaxis": {"tickformat": ".0%", "title": "NTM revenue growth"}, "yaxis": {"type": "log", "title": "EV / NTM sales"},
                         "margin": {"l": 60, "r": 20, "t": 40, "b": 50}, "legend": {"orientation": "h", "y": 1.08}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
    figs = {"pw": fig_pw, "rc": fig_rc, "bt": fig_bt, "corr": fig_corr, "vg": fig_vg}
    if hist_fig is not None:
        piv_w = hist_fig.pivot(index="run_axis", columns="ticker", values="weight").fillna(0)
        piv_r = hist_fig.pivot(index="run_axis", columns="ticker", values="rank")
        figs["hw"] = {"data": [{"type": "scatter", "mode": "lines", "stackgroup": "one", "name": t, "x": piv_w.index.tolist(), "y": piv_w[t].round(4).tolist()} for t in piv_w.columns],
                      "layout": {"title": {"text": "Target weights over runs", "x": 0}, "yaxis": {"tickformat": ".0%"}, "margin": {"l": 50, "r": 20, "t": 40, "b": 30}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
        figs["hr"] = {"data": [{"type": "scatter", "mode": "lines+markers", "name": t, "x": piv_r.index.tolist(), "y": piv_r[t].tolist()} for t in piv_r.columns],
                      "layout": {"title": {"text": "Rank over runs (1 = best)", "x": 0}, "yaxis": {"autorange": "reversed"}, "margin": {"l": 50, "r": 20, "t": 40, "b": 30}, "paper_bgcolor": "rgba(0,0,0,0)", "plot_bgcolor": "rgba(0,0,0,0)"}}
    script = "<script>const FIGS=" + _plotly_json(figs) + """;
function drawAll(){const dark=matchMedia('(prefers-color-scheme: dark)').matches||document.documentElement.dataset.theme==='dark';
const font={color:dark?'#c3c2b7':'#52514e',family:'-apple-system,Segoe UI,Helvetica,Arial,sans-serif'};
for(const id in FIGS){const el=document.getElementById(id);if(!el)continue;const lay=Object.assign({},FIGS[id].layout,{font,xaxis:Object.assign({gridcolor:dark?'#2f2f2c':'#ebeae5'},FIGS[id].layout.xaxis||{}),yaxis:Object.assign({gridcolor:dark?'#2f2f2c':'#ebeae5'},FIGS[id].layout.yaxis||{})});
Plotly.newPlot(id,FIGS[id].data,lay,{responsive:true,displaylogo:false});}}
if(window.Plotly){drawAll();}else{document.addEventListener('DOMContentLoaded',drawAll);}
</script>"""
    body = CSS + JS + "\n".join(parts) + f'<script src="{PLOTLY}"></script>' + script
    DASHBOARD.mkdir(parents=True, exist_ok=True)
    (DASHBOARD / "artifact.html").write_text("<title>AI Semi Value Chain Monitor</title>\n" + body, encoding="utf-8")
    full = ("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
            "<title>AI & Semiconductor Value Chain — Daily KPI Monitor</title></head><body>" + body + "</body></html>")
    out = DASHBOARD / "index.html"
    out.write_text(full, encoding="utf-8")
    return out
